			assert.ok( c.getHex() == 0xFA8072, 'Hex: ' + c.getHex() );
			assert.ok( c.r == 0xFA / 0xFF, 'Red: ' + c.r );
			assert.ok( c.g == 0x80 / 0xFF, 'Green: ' + c.g );
			assert.ok( c.b == 0x72 / 0xFF, 'Blue: ' + c.b );

		} );

		QUnit.test( 'setRGB', ( assert ) => {

