			assert.ok( hsl.h == 0.75, 'hue: ' + hsl.h );
			assert.ok( hsl.s == 1.00, 'saturation: ' + hsl.s );
			assert.ok( hsl.l == 0.25, 'lightness: ' + hsl.l );

		} );

		QUnit.test( 'setStyle', ( assert ) => {

			var a = new Color();

