			assert.ok( b.g == 0x80 / 255, 'Green: ' + b.g );
			assert.ok( b.b == 0x80 / 255, 'Blue: ' + b.b );

		} );

		QUnit.test( 'copySRGBToLinear', ( assert ) => {

