			assert.numEqual( c.g, 0.5, 'Green c: ' + c.g + ' Green c2: ' + c2.g );
			assert.numEqual( c.b, 0.9, 'Blue c: ' + c.b + ' Blue c2: ' + c2.b );

		} );

		QUnit.test( 'convertSRGBToLinear', ( assert ) => {

			var c = new Color();
			c.setRGB( 0.3, 0.5, 0.9 );
